-- Generated by drizzle-kit, then made idempotent: an existing database already has
-- this schema from the pre-Drizzle server/migrate.ts, so this only records the baseline there.
CREATE TABLE IF NOT EXISTS "votes" (
	"id" serial PRIMARY KEY NOT NULL,
	"name" text NOT NULL,
	"option" text NOT NULL,
	"week_start" bigint NOT NULL,
	"timestamp" bigint NOT NULL,
	CONSTRAINT "votes_week_start_name_key" UNIQUE("week_start","name"),
	CONSTRAINT "votes_option_check" CHECK ("votes"."option" IN ('yes', 'no', 'could-be-convinced'))
);
